thread-pool.pseudocode:
class ThreadPool:
    def __init__(self, n, queue_max):
        self.q = BlockingQueue(queue_max)  # 작업 큐
        for _ in range(n):  # 스레드를 미리 생성
            start_thread(self.worker)

    def submit(self, task):
        if not self.q.offer(task):  # 큐가 가득 참
            raise RejectedError()  # 거부 정책

    def worker(self):
        while True:
            task = self.q.take()  # 작업 없으면 대기
            try:
                task()
            except Exception as e:
                log(e)  # 스레드는 종료 없이 재사용

three-way-partitioning.pseudocode:
def partition3(a, lo, hi):  # 네덜란드 국기 분할
    pivot = a[lo]
    lt, i, gt = lo, lo, hi
    while i <= gt:
        if a[i] < pivot:
            a[lt], a[i] = a[i], a[lt]
            lt += 1
            i += 1
        elif a[i] > pivot:
            a[i], a[gt] = a[gt], a[i]
            gt -= 1  # i 유지: 교환해 온 값은 미검사
        else:
            i += 1
    return lt, gt  # a[lt..gt] 모두 pivot

def quicksort3(a, lo, hi):
    if lo >= hi:
        return
    lt, gt = partition3(a, lo, hi)
    quicksort3(a, lo, lt - 1)  # 같은 키 구간은 제외
    quicksort3(a, gt + 1, hi)
